// src/app/services/auth.service.ts

import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  // A propriedade que armazena o ID do usuário
  private currentUserId: number = 0; // Inicializa com 0 ou null

  constructor() {
    // 💡 Na prática, este método deve ler o ID do Token JWT ou do localStorage
    this.loadUserSession(); 
  }

  // Método que o TransactionService irá chamar
  public getUserId(): number {
    // Retorna o ID do usuário.
    // Lembre-se: se não houver usuário logado, isso deve retornar um erro ou null.
    return this.currentUserId; 
  }

  // Exemplo de como você pode carregar o ID após o login
  private loadUserSession(): void {
    // Exemplo: Pegar o ID do token JWT decodificado ou de algum lugar seguro.
    // Para teste:
    this.currentUserId = 42; 
  }
}
